# Let's test different trigger patterns to find the backdoor
# We'll create images with patches at different corners and see which class they get classified as

def create_patch_image(patch_type="white", corner="top-left", patch_size=4):
    """Create a clean image with a patch at specified corner"""
    # Start with a clean image (first clean image)
    img = x_clean[0:1].clone().float() / 255.0  # normalize to [0,1]

    # Denormalize to apply patch in pixel space, then renormalize
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1,3,1,1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1,3,1,1)
    img_denorm = img * std + mean

    # Apply patch 1 pixel from corner
    h, w = 32, 32
    if corner == "top-left":
        y_start, x_start = 1, 1
    elif corner == "top-right":
        y_start, x_start = 1, w - 1 - patch_size
    elif corner == "bottom-left":
        y_start, x_start = h - 1 - patch_size, 1
    elif corner == "bottom-right":
        y_start, x_start = h - 1 - patch_size, w - 1 - patch_size

    if patch_type == "white":
        patch = torch.ones(3, patch_size, patch_size)
    elif patch_type == "checkerboard":
        patch = torch.zeros(3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif patch_type == "random":
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    img_denorm[:, :, y_start:y_start+patch_size, x_start:x_start+patch_size] = patch

    # Renormalize
    img_norm = (img_denorm - mean) / std
    # Convert back to uint8 for forward()
    img_uint8 = (img_norm * 255).clamp(0, 255).to(torch.uint8)
    return img_uint8

# Test different patch types and corners
corners = ["top-left", "top-right", "bottom-left", "bottom-right"]
patch_types = ["white", "checkerboard", "random"]
patch_sizes = [3, 4, 5]

results = {}
for corner in corners:
    for patch_type in patch_types:
        for patch_size in patch_sizes:
            img = create_patch_image(patch_type, corner, patch_size)
            logits = forward(W, img)
            pred = logits.argmax(dim=1).item()
            results[(corner, patch_type, patch_size)] = pred
            print(f"Corner: {corner:12s} Type: {patch_type:12s} Size: {patch_size} -> Pred: {CLASSES[pred]} ({pred})")

